   282	async function restoreMcpAppResultImpl(
   283		args: {
   284			tool_call_id?: string | number;
   285			snapshot_capability?: string;
   286			tool_name?: string;
   287		},
   288		_env: Env,
   289		ctx: ToolContext,
   290	) {
   291		const sql = getDb();
   292		const identity =
   293			args.tool_call_id === undefined
   294				? null
   295				: snapshotIdentity(ctx, args.tool_call_id);
   296		let row: SnapshotRow | undefined;
   297		if (identity) {
   298			[row] = await sql<SnapshotRow>`
   299				SELECT body, tool_name
   300				FROM public.mcp_app_result_snapshots
   301				WHERE organization_id = ${identity.organizationId}
   302					AND client_id = ${identity.clientId}
   303					AND user_id = ${identity.userId}
   304					AND conversation_key = ${identity.conversationKey}
   305					AND tool_call_key = ${identity.toolCallKey}
   306					AND expires_at > now()
   307			`;
   308		}
   309	
   310		const capabilityIdentity = snapshotIdentity(ctx, args.snapshot_capability);
   311		if (!row && capabilityIdentity) {
   312			const candidates = await sql<SnapshotLookupRow>`
   313				SELECT body, tool_name, tool_call_key
   314				FROM public.mcp_app_result_snapshots
   315				WHERE organization_id = ${capabilityIdentity.organizationId}
   316					AND client_id = ${capabilityIdentity.clientId}
   317					AND user_id = ${capabilityIdentity.userId}
   318					AND conversation_key = ${capabilityIdentity.conversationKey}
   319					AND expires_at > now()
   320				ORDER BY updated_at DESC, tool_call_key
   321				LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
   322			`;
   323			row = candidates.find((candidate) => {
   324				const snapshot = parseSnapshot(candidate.body);
   325				return snapshot?.bindingKey === capabilityIdentity.toolCallKey;
   326			});
   327		}
   328		if (!row || (args.tool_name && row.tool_name !== args.tool_name))
   329			return { found: false, view_state: {} };
   330		const snapshot = parseSnapshot(row.body);
   331		if (!snapshot || snapshot.toolName !== row.tool_name) {
   332			logger.warn(
   333				{ toolName: row.tool_name },
   334				"Discarded unreadable MCP App result snapshot",
   335			);
   336			return { found: false, view_state: {} };
   337		}
   338		return {
   339			found: true,
   340			tool_name: snapshot.toolName,
   341			data: snapshot.data,
   342			view_state: snapshot.viewState,
   343		};
   344	}
