import {
	act,
	fireEvent,
	render,
	screen,
	waitFor,
} from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	close: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() {
			return { isError: false };
		}
	},
	PostMessageTransport: class {
		close = bridge.close;
	},
}));

type CompatParent = EventTarget & {
	location: { origin: string };
	openai?: unknown;
};

const originalParentDescriptor = Object.getOwnPropertyDescriptor(
	window,
	"parent",
);
const originalOpenAiDescriptor = Object.getOwnPropertyDescriptor(
	window,
	"openai",
);

function restoreWindowProperty(
	name: "parent" | "openai",
	descriptor: PropertyDescriptor | undefined,
) {
	if (descriptor) Object.defineProperty(window, name, descriptor);
	else Reflect.deleteProperty(window, name);
}

describe("MCP app host compatibility wiring", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
		bridge.callServerTool.mockResolvedValue({ isError: false });
	});

	afterEach(() => {
		restoreWindowProperty("parent", originalParentDescriptor);
		restoreWindowProperty("openai", originalOpenAiDescriptor);
		document.documentElement.classList.remove("dark");
	});

	it("hydrates from ChatGPT's outer sandbox and applies later updates", async () => {
		const setWidgetState = vi.fn();
		Object.defineProperty(window, "openai", {
			configurable: true,
			value: {
				widgetState: {
					privateContent: {
						lobuViewSnapshot: {
							version: 1,
							data: { title: "Stale inner snapshot" },
						},
					},
				},
			},
		});
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: window.location.origin },
			openai: {
				toolOutput: { title: "Preloaded result" },
				setWidgetState,
				toolResponseMetadata: {
					mcp_tool_result: {
						_meta: { "lobu/approval-capability": "preloaded-capability" },
					},
				},
			},
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { callTool, data } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title}</span>
					<button
						type="button"
						onClick={() =>
							void callTool("resolve_lobu_approval", { decision: "approve" })
						}
					>
						Approve
					</button>
				</>
			);
		}

		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);

		expect(await screen.findByText("Preloaded result")).toBeInTheDocument();
		expect(screen.queryByText("Stale inner snapshot")).not.toBeInTheDocument();
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		expect(document.documentElement).not.toHaveClass("dark");
		act(() => {
			for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) {
				handler({ theme: "dark" });
			}
		});
		expect(document.documentElement).toHaveClass("dark");
		act(() => {
			for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) {
				handler({ theme: "light" });
			}
		});
		expect(document.documentElement).not.toHaveClass("dark");
		await waitFor(() =>
			expect(setWidgetState).toHaveBeenCalledWith({
				privateContent: {
					lobuViewSnapshot: {
						version: 1,
						data: { title: "Preloaded result" },
					},
				},
			}),
		);

		act(() => {
			compatParent.dispatchEvent(
				new CustomEvent("openai:set_globals", {
					detail: {
						globals: {
							toolOutput: { title: "Updated result" },
							toolResponseMetadata: {
								mcp_tool_result: {
									_meta: {
										"lobu/approval-capability": "updated-capability",
									},
								},
							},
						},
					},
				}),
			);
		});

		expect(await screen.findByText("Updated result")).toBeInTheDocument();
		await waitFor(() =>
			expect(setWidgetState).toHaveBeenLastCalledWith({
				privateContent: {
					lobuViewSnapshot: {
						version: 1,
						data: { title: "Updated result" },
					},
				},
			}),
		);
		fireEvent.click(screen.getByRole("button", { name: "Approve" }));
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "resolve_lobu_approval",
				arguments: { decision: "approve" },
				_meta: { "lobu/approval-capability": "updated-capability" },
			}),
		);
	});

	it("skips unrelated inner widget state for an outer Lobu snapshot", async () => {
		Object.defineProperty(window, "openai", {
			configurable: true,
			value: { widgetState: { privateContent: { anotherAppKey: "ignore" } } },
		});
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: window.location.origin },
			openai: {
				widgetState: {
					privateContent: {
						lobuViewSnapshot: {
							version: 1,
							data: { title: "Outer cached result" },
						},
					},
				},
			},
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data } = useMcpApp<{ title: string }>();
			return <span>{data?.title}</span>;
		}

		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);

		expect(await screen.findByText("Outer cached result")).toBeInTheDocument();
	});

	it("persists a standard MCP tool result for the next page lifetime", async () => {
		const setWidgetState = vi.fn();
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: window.location.origin },
			openai: { setWidgetState },
		});
		setWidgetState.mockImplementation((widgetState) => {
			compatParent.openai = { setWidgetState, widgetState };
			compatParent.dispatchEvent(
				new CustomEvent("openai:set_globals", {
					detail: { globals: { widgetState } },
				}),
			);
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data } = useMcpApp<{
				title: string;
				actions?: Array<Record<string, unknown>>;
			}>();
			return (
				<>
					<span>{data?.title}</span>
					<span>{data?.actions?.length ?? 0} actions</span>
				</>
			);
		}

		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: {
						title: "Standard result",
						actions: [
							{ id: "approve", tool: "resolve_lobu_approval" },
							{ id: "review", href: "https://lobu.ai/runs/42" },
						],
					},
				});
			}
		});

		expect(await screen.findByText("Standard result")).toBeInTheDocument();
		expect(screen.getByText("2 actions")).toBeInTheDocument();
		expect(setWidgetState).toHaveBeenCalledWith({
			privateContent: {
				lobuViewSnapshot: {
					version: 1,
					data: {
						title: "Standard result",
						actions: [{ id: "review", href: "https://lobu.ai/runs/42" }],
					},
				},
			},
		});
		expect(setWidgetState).toHaveBeenCalledTimes(1);
	});

	it("binds a live result snapshot to the host card id", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		bridge.hostContext = {
			toolInfo: { id: "host-card-77", tool: { name: "query_sdk" } },
		};
		bridge.callServerTool.mockImplementation(async ({ name }) => ({
			isError: false,
			...(name === "save_lobu_app_state"
				? { structuredContent: { saved: true } }
				: {}),
		}));

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, setViewState } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title}</span>
					<button
						type="button"
						onClick={() => setViewState("details.open", true)}
					>
						Expand
					</button>
				</>
			);
		}

		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: { title: "Live result" },
					_meta: {
						"lobu/mcp-app-snapshot-capability": "single-use-token",
					},
				});
			}
		});

		expect(await screen.findByText("Live result")).toBeInTheDocument();
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "save_lobu_app_state",
				arguments: {
					tool_call_id: "host-card-77",
					tool_name: "query_sdk",
					view_state: {},
					snapshot_capability: "single-use-token",
				},
				_meta: {
					"lobu/mcp-app-snapshot-capability": "single-use-token",
				},
			}),
		);
		fireEvent.click(screen.getByRole("button", { name: "Expand" }));
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "save_lobu_app_state",
				arguments: {
					tool_call_id: "host-card-77",
					tool_name: "query_sdk",
					view_state: { "details.open": true },
				},
			}),
		);
	});

